static netdev_tx_t pch_gbe_xmit_frame ( struct sk_buff * skb , struct net_device * netdev ) { struct pch_gbe_adapter * adapter = netdev_priv ( netdev ) ; struct pch_gbe_tx_ring * tx_ring = adapter -> tx_ring ; if ( unlikely ( ! PCH_GBE_DESC_UNUSED ( tx_ring ) ) ) { netif_stop_queue ( netdev , NULL ) ; netdev_dbg ( netdev , "Return : BUSY  next_to use : 0x%08x  next_to clean : 0x%08x\n" , tx_ring -> next_to_use , tx_ring -> next_to_clean ) ; return NETDEV_TX_BUSY ; } pch_gbe_tx_queue ( adapter , tx_ring , skb ) ; return NETDEV_TX_OK ; } 